class Component extends DCLogic {
  state = { ready: false }
  componentDidMount() {
    if (!RELAY)
      this._i = setInterval(() => {
        if (RELAY) {
          clearInterval(this._i)
          this.forceUpdate()
        }
      }, 40)
    this._t = setTimeout(() => this.setState({ ready: true }), 60)
  }
  componentWillUnmount() {
    clearInterval(this._i)
    clearTimeout(this._t)
  }
  renderVals() {
    const R = RELAY ?? EMPTY,
      m = /[?&]kind=(\w+)/.exec(dcSearch()),
      k = this.props.kind ?? (m && C[m[1]] ? m[1] : 'collections')
    const [tag, code, rgb, single, desc, stats, look] = C[k],
      label = R.CAT[k]?.label ?? k,
      r = this.state.ready
    return {
      c: {
        kind: k,
        label,
        tag,
        code,
        rgb,
        single,
        desc,
        accent: R.CAT[k]?.accent ?? '#fff',
        count: R.CAT[k]?.count ?? '',
        stats: stats.map(([k2, v]) => ({ k: k2, v })),
        look: look.map(([t, d], i) => ({ n: String(i + 1).padStart(2, '0'), t, d })),
      },
      ld: {
        op: r ? 1 : 0,
        tf: r ? 'none' : 'translateY(18px)',
        icon: r ? 'scale(1) rotate(0)' : 'scale(.6) rotate(-14deg)',
      },
      providers: R.providers
        .filter((p) => p.kind === k)
        .sort((a, b) => b.score - a.score)
        .slice(0, 8)
        .map((p) => ({ ...p, sw: p.score + '%' })),
      others: Object.keys(C)
        .filter((x) => x !== k)
        .map((x) => ({ kind: x, label: R.CAT[x]?.label ?? x, href: 'Relay%20Category.dc.html?kind=' + x })),
    }
  }
}

